exercises.solution:
def flatten_dict(d, prefix=""):
    flat = {}
    for key, value in d.items():
        full = f"{prefix}.{key}" if prefix else key
        if isinstance(value, dict):
            flat.update(flatten_dict(value, full))
        else:
            flat[full] = value
    return flat

